/**
 * Security-critical constants.
 *
 * @remarks
 * Every regular expression in this file is linear-time or tightly bounded and is
 * only ever executed against input that has already been hard-truncated by
 * {@link HARD_TEXT_CAP} characters, which keeps the sanitizer ReDoS-safe.
 */

/** Stable schema version stamped onto every persisted record. */
export const SCHEMA_VERSION = 1;

/** Placeholder substituted for anything the sanitizer removes. */
export const REDACTED = '[REDACTED]';

/** Separator used when joining fingerprint parts. `U+241F` is a unit separator glyph. */
export const FINGERPRINT_SEPARATOR = '\u241F';

/** Fixed name of the singleton key used to survive duplicate bundle copies. */
export const SINGLETON_KEY = Symbol.for('logvault@1');

/** Reserved logger prefixes whose messages are internal and never persisted. */
export const RESERVED_LOG_PREFIXES: readonly string[] = [
  '[ErrorTracking]',
  '[LogTracking]',
  '[Telemetry]',
  '[DiagnosticsExport]',
];

/**
 * Matched against a lowercased object key with `[-_\s]` stripped out, so that
 * `access_token`, `accessToken` and `ACCESS TOKEN` all normalise to `accesstoken`.
 */
export const SENSITIVE_KEY_PATTERN =
  /(authorization|cookie|token|password|passwd|pwd|secret|apikey|accesskey|privatekey|credential|session|signature|bearer|otp|^auth$|email|phone)/;

/** JSON Web Token shape, used to scrub tokens embedded in free text. */
export const JWT_PATTERN = /\beyJ[\w-]{5,}\.[\w-]{5,}\.[\w-]*/g;

/** `Bearer <secret>` / `Basic <secret>` / `Token <secret>` authorisation schemes. */
export const AUTH_SCHEME_PATTERN = /\b(Bearer|Basic|Token)\s+[\w.~+/=-]{6,}/gi;

/** Loose e-mail shape used to scrub addresses from free text. */
export const EMAIL_PATTERN = /[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g;

/** Query string / fragment stripping for `key=value` secrets in free text. */
export const KV_SECRET_PATTERNS: readonly RegExp[] = [
  /((?:token|access_token|refresh_token|id_token)["']?\s*[=:]\s*["']?)([^\s&"',;]+)/gi,
  /((?:password|pwd|secret|client_secret)["']?\s*[=:]\s*["']?)([^\s&"',;]+)/gi,
  /((?:api_key|api-key|apikey|session|sessionid)["']?\s*[=:]\s*["']?)([^\s&"',;]+)/gi,
  // `phone` is in SENSITIVE_KEY_PATTERN, so free text has to honour it too —
  // otherwise `phone=+1415…` in a log message would survive while the same value
  // under a `phone` object key would not.
  /((?:phone|mobile|msisdn|telephone|email)["']?\s*[=:]\s*["']?)([^\s&"',;]+)/gi,
];

/** Query-string cache-buster stripping inside stack frames (Vite `?t=`, `?v=`). */
export const STACK_QUERY_PATTERN = /\?[^\s:)]*(?=:\d+(?::\d+)?)/g;

/**
 * Long opaque tokens with no `key=value` context, e.g. `sk_live_…`, `ghp_…`,
 * a session id or a content hash.
 *
 * @remarks
 * Written without lookbehind so it runs on every engine in the support matrix. The
 * leading group is preserved by the replacement, and the trailing lookahead keeps
 * the match linear — the whole pattern is bounded and ReDoS-safe.
 *
 * The bounds are tuned to the real world. A lower bound of 32 catches the common
 * shapes of a leaked credential — a Stripe-style `sk_live_…`, a bare MD5/SHA
 * fragment, a dashless UUID, a GitHub token — while 32 characters is long enough
 * that ordinary prose never matches. The upper bound of 200 matters too: an
 * arbitrarily long run of word characters is far more likely to be prose or a
 * serialised structure, and redacting those wholesale would destroy the
 * diagnostic value of the message, so they are left for length truncation.
 */
export const LONG_SECRET_TEXT_PATTERN = /(^|[^\w-])([\w-]{32,200})(?=[^\w-]|$)/g;

/** Recognises a chunk / dynamic-import failure from its message. */
export const CHUNK_ERROR_PATTERN =
  /(Failed to fetch dynamically imported module|error loading dynamically imported module|Importing a module script failed|Loading chunk [\w-]+ failed|ChunkLoadError|Unable to preload CSS|Failed to load module script)/i;

/** Recognises a path segment that is really an identifier, for fingerprint grouping. */
export const DIGITS_ONLY_PATTERN = /^\d+$/;
/** UUID v1–v8 (and nil) path segment. */
export const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
/** Long hex blob path segment (commit SHAs, content hashes, session ids). */
export const LONG_HEX_PATTERN = /^[0-9a-f]{24,}$/i;
/**
 * Long `[\w-]` run that is not obviously an ordinary word, used to redact a URL
 * path segment that is really an identifier or a token.
 *
 * @remarks
 * The threshold is 32 rather than 40 so it agrees with
 * {@link LONG_SECRET_TEXT_PATTERN}, and so it covers the shapes that actually
 * leak: a Stripe-style key, a dashless UUID, a bare hash. A 40-character floor
 * silently misses a 39-character real key.
 */
export const LONG_SECRET_PATTERN = /^[\w-]{32,}$/;

// ---------------------------------------------------------------------------
// Bounded-work limits
// ---------------------------------------------------------------------------

/** Maximum characters any regex is ever executed against. */
export const HARD_TEXT_CAP = 20_000;
/** Maximum nesting depth walked by `sanitizeValue`. */
export const MAX_DEPTH = 4;
/** Maximum own enumerable keys copied from a plain object. */
export const MAX_KEYS = 30;
/** Maximum array items copied from an array. */
export const MAX_ARRAY_ITEMS = 20;
/** Maximum length of a sanitised free-text/string value. */
export const MAX_STRING_LENGTH = 2_000;
/** Maximum length of an error message. */
export const MAX_MESSAGE_LENGTH = 1_000;
/** Maximum length of an error stack. */
export const MAX_STACK_LENGTH = 8_000;
/** Maximum length of a React/Vue/Angular component stack. */
export const MAX_COMPONENT_STACK_LENGTH = 4_000;
/** Maximum `cause` chain depth normalised into `causes[]`. */
export const MAX_CAUSE_DEPTH = 3;
/** Maximum sub-errors read out of an `AggregateError`. */
export const MAX_AGGREGATE_ERRORS = 5;
/** Maximum number of tags accepted on an error record. */
export const MAX_TAGS = 20;
/** Maximum length of a tag key. */
export const MAX_TAG_KEY_LENGTH = 50;
/** Maximum length of a tag value. */
export const MAX_TAG_VALUE_LENGTH = 200;
/** Maximum `userAgent` characters stored in an environment block. */
export const MAX_USER_AGENT_LENGTH = 500;
/** Maximum log arguments captured per call. */
export const MAX_LOG_ARGS = 5;
/** Maximum errors buffered before `initTelemetry` runs. */
export const PRE_INIT_ERROR_BUFFER_SIZE = 50;
/** Maximum length of a log message. */
export const MAX_LOG_MESSAGE_LENGTH = 1_000;
/** Maximum length of a route string. */
export const MAX_ROUTE_LENGTH = 300;
/** Maximum length of a sanitised URL. */
export const MAX_URL_LENGTH = 2_000;
/** Query values that survive redaction when their key is allow-listed. */
export const MAX_ALLOWED_QUERY_VALUE_LENGTH = 100;

/** Query parameter names whose *values* survive redaction by default. */
export const DEFAULT_ALLOWED_QUERY_PARAMS: readonly string[] = [
  'limit',
  'offset',
  'page',
  'pageSize',
  'size',
  'sort',
  'order',
  'scope',
  'lng',
  'lang',
  'type',
];

/**
 * Sources that represent an error the application did not explicitly handle.
 * `handled` is derived as `!UNHANDLED_SOURCES.has(source)`.
 */
export const UNHANDLED_SOURCES: ReadonlySet<string> = new Set([
  'window',
  'unhandledrejection',
  'resource',
  'chunk',
  'csp',
  'worker',
]);

/** Suffix appended to truncated strings, prefixed with the dropped character count. */
export function truncationSuffix(dropped: number): string {
  return `…[truncated ${String(dropped)}]`;
}
