/**
 * Logger constants: level ladder, numeric priorities and reserved prefixes.
 *
 * @packageDocumentation
 */

import { RESERVED_LOG_PREFIXES } from '../errors/constants.js';

/** A persistable log level. `off` disables persistence entirely. */
export type LogLevel = 'trace' | 'debug' | 'info' | 'warn' | 'error';

/** A console verbosity setting, which additionally accepts `off`. */
export type LogLevelSetting = LogLevel | 'off';

/** Numeric priority ladder. Higher wins. */
export const LOG_LEVEL_PRIORITY: Readonly<Record<LogLevel, number>> = {
  trace: 10,
  debug: 20,
  info: 30,
  warn: 40,
  error: 50,
};

/** Ascending level order, useful for `>= level` comparisons and UI filters. */
export const LOG_LEVELS: readonly LogLevel[] = ['trace', 'debug', 'info', 'warn', 'error'];

/** Reserved internal prefixes. Messages beginning with one are never persisted. */
export const INTERNAL_PREFIXES: readonly string[] = RESERVED_LOG_PREFIXES;

/** Console prefix used by the library's own diagnostics writer. */
export const CONSOLE_PREFIX = '[rm-logvault]';

/** Maximum number of log calls buffered before `initTelemetry` runs. */
export const PRE_INIT_LOG_BUFFER_SIZE = 50;

/** Logs are flushed when this many entries are buffered. */
export const LOG_FLUSH_BATCH_SIZE = 50;

/** Logs are flushed at most this long after the first buffered entry. */
export const LOG_FLUSH_INTERVAL_MS = 1_000;

/** Numeric priority for a level setting. `off` maps to `Infinity` so nothing passes. */
export function levelPriority(level: LogLevelSetting): number {
  return level === 'off' ? Number.POSITIVE_INFINITY : LOG_LEVEL_PRIORITY[level];
}

/**
 * Whether `actual` is at or above `threshold`.
 *
 * @param actual - the level a record was emitted at
 * @param threshold - the configured minimum
 */
export function meetsLevel(actual: LogLevel, threshold: LogLevelSetting): boolean {
  if (threshold === 'off') return false;
  return LOG_LEVEL_PRIORITY[actual] >= LOG_LEVEL_PRIORITY[threshold];
}
