/**
 * The single guarded `console` writer.
 *
 * @remarks
 * This is the **only** module in the library permitted to touch `console.*`
 * (enforced by an ESLint override in `eslint.config.js`). Centralising it buys
 * three guarantees:
 *
 * - `console` missing, deleted, or replaced by a hostile object never throws.
 * - Output is styled in browsers and plain text elsewhere, so terminal logs stay
 *   readable in Node/SSR.
 * - The library can never recurse into itself through its own console output.
 *
 * @packageDocumentation
 */

import { safeGet } from '../core/env.js';
import type { LogLevel } from './logger.constants.js';
import { CONSOLE_PREFIX } from './logger.constants.js';

/** Prefix styling used when the environment renders `%c` directives. */
const PREFIX_STYLE = 'color:#8a8a8a;font-weight:600';
/** Message styling used when the environment renders `%c` directives. */
const MESSAGE_STYLE = 'color:inherit';

/** Writes formatted lines to the host console. */
export interface ConsoleWriter {
  /**
   * Emit one line.
   *
   * @param level - the level, which selects the console method
   * @param message - the message text
   * @param args - extra arguments forwarded to the console method
   */
  write(level: LogLevel, message: string, args: readonly unknown[]): void;
  /** Whether a console object was found the last time {@link ConsoleWriter.write} ran. */
  isAvailable(): boolean;
}

/** Resolve `globalThis.console` defensively. */
function resolveConsole(): Record<string, unknown> | undefined {
  try {
    const candidate: unknown = Reflect.get(globalThis, 'console');
    if (candidate === null || typeof candidate !== 'object') return undefined;
    return candidate as Record<string, unknown>;
  } catch {
    return undefined;
  }
}

/** Whether `%c` directives are likely to be rendered (i.e. a real browser). */
function supportsStyling(): boolean {
  try {
    return typeof Reflect.get(globalThis, 'document') === 'object';
  } catch {
    return false;
  }
}

/** Map a level onto the closest console method. */
function methodFor(level: LogLevel): string {
  switch (level) {
    case 'trace':
      return 'trace';
    case 'debug':
      return 'debug';
    case 'info':
      return 'info';
    case 'warn':
      return 'warn';
    default:
      return 'error';
  }
}

/**
 * Create the guarded console writer.
 *
 * @returns a {@link ConsoleWriter} that never throws
 *
 * @example
 * ```ts
 * import { createConsoleWriter } from '@codewithrajat/rm-logvault';
 *
 * const writer = createConsoleWriter();
 * writer.write('warn', '[Checkout] slow response', [{ ms: 4200 }]);
 * ```
 */
export function createConsoleWriter(): ConsoleWriter {
  let available = false;

  const write = (level: LogLevel, message: string, args: readonly unknown[]): void => {
    try {
      const consoleObject = resolveConsole();
      available = consoleObject !== undefined;
      if (consoleObject === undefined) return;

      const methodName = methodFor(level);
      let method = safeGet(consoleObject, methodName);
      if (typeof method !== 'function') method = safeGet(consoleObject, 'log');
      if (typeof method !== 'function') return;

      const payload: unknown[] = supportsStyling()
        ? [`%c${CONSOLE_PREFIX}%c ${message}`, PREFIX_STYLE, MESSAGE_STYLE, ...args]
        : [`${CONSOLE_PREFIX} ${message}`, ...args];

      Reflect.apply(method as (...params: unknown[]) => unknown, consoleObject, payload);
    } catch {
      // A broken console must never break the host application.
    }
  };

  return {
    write,
    isAvailable: (): boolean => {
      if (!available) available = resolveConsole() !== undefined;
      return available;
    },
  };
}
